const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check warranties table schema
const wCols = db.pragma('table_info(warranties)');
console.log('=== warranties schema ===');
console.log(JSON.stringify(wCols, null, 2));

// Check for order ORD-E0E671
console.log('\n=== Order ORD-E0E671 ===');
let order = db.prepare(\"SELECT * FROM orders WHERE order_id = ?\").get('ORD-E0E671');
if (!order) order = db.prepare(\"SELECT * FROM orders WHERE order_id = ?\").get('#ORD-E0E671');
console.log(JSON.stringify(order, null, 2));

// Try with different prefix patterns
const allOrders = db.prepare(\"SELECT order_id FROM orders WHERE order_id LIKE '%E0E671%'\").all();
console.log('\n=== Matching orders ===');
console.log(JSON.stringify(allOrders));

// Check warranties for this order
const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id LIKE '%E0E671%'\").all();
console.log('\n=== Warranties ===');
console.log(JSON.stringify(warranties, null, 2));
"

